    # Banker's rounding to whole cents; str() keeps float rates out of the math.
    tax = Decimal(amount_cents) * Decimal(str(rate))
    return int(tax.quantize(Decimal(1), rounding=ROUND_HALF_EVEN))


def invoice_tax(lines, rate):
    # Round each line's tax separately, then sum; never round the invoice total.
    return sum(tax_for(line["quantity"] * line["unit_cents"], rate) for line in lines)"
